def apply_interface() -> None:
    st.markdown(
        """
        <style>
        @import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@500;600;700;800&family=Inter:wght@400;500;600;700&display=swap');
        :root { color-scheme: dark; }
        html, body, [data-testid="stAppViewContainer"] {
            background: radial-gradient(ellipse at 50% -10%, #49320c 0%, transparent 42%),
                        linear-gradient(145deg, #090a08 0%, #17140b 52%, #080907 100%);
            color: #f4e7b4; font-family: Inter, sans-serif;
        }
        [data-testid="stHeader"] { background: transparent; }
        .block-container { max-width: 1500px; padding-top: 1.2rem; padding-bottom: .8rem; }
        [data-testid="stSidebar"] { background: linear-gradient(180deg,#171309,#0c0b08); border-right:1px solid rgba(229,190,89,.18); }
        [data-testid="stSidebar"] [data-testid="stMarkdownContainer"] p { color:#d6c58e; }
        .gh-title { text-align:center; font-family:Cinzel,serif; font-size:clamp(28px,4vw,48px); font-weight:800; letter-spacing:.14em; color:#f4d46f; text-shadow:0 0 24px rgba(224,171,45,.24); margin:0; }
        .gh-sub { text-align:center; color:#b9a56c; letter-spacing:.25em; font-size:10px; margin:.2rem 0 1rem; }
        .gh-frame { border:1px solid rgba(229,190,89,.25); border-radius:16px; overflow:hidden; box-shadow:0 18px 70px rgba(0,0,0,.42); }
        div[data-testid="stSlider"] label { color:#f2d987 !important; font-weight:600; }
        div[data-testid="stSlider"] [data-testid="stThumbValue"] { color:#f4d46f !important; }
        footer { visibility:hidden; }
        </style>
        """,
        unsafe_allow_html=True,
    )


def build_scene_html(wing_size: float) -> str:
    settings = json.dumps({"wingSize": float(wing_size)})
    scales = json.dumps(SCALE_LAYOUT, separators=(",", ":"))
    html = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#080906}
#stage{position:relative;width:100%;height:760px;overflow:hidden;background:radial-gradient(ellipse at 50% 58%,rgba(141,103,26,.22),transparent 48%),linear-gradient(180deg,#17170f,#090a08 78%)}
#view{display:block;width:100%;height:100%;outline:none}#err{display:none;position:absolute;left:14px;right:14px;bottom:14px;padding:12px;border:1px solid #b65c42;border-radius:8px;background:#24120e;color:#ffd6c9;font:12px/1.5 Arial;white-space:pre-wrap;z-index:10}
#tag{position:absolute;left:18px;top:16px;color:rgba(246,220,142,.68);font:10px Cinzel,serif;letter-spacing:.22em;pointer-events:none}
#hint{position:absolute;right:18px;bottom:16px;color:rgba(246,220,142,.48);font:9px Arial;letter-spacing:.14em;pointer-events:none}
</style></head><body><div id="stage"><div id="tag">MONARCH CLASS TITAN · GHIDORAH</div><div id="hint">DRAG TO ORBIT · SCROLL TO ZOOM</div><div id="err"></div><canvas id="view"></canvas></div>
<script type="module">
import * as THREE from "https://esm.sh/three@0.160.0";
import { OrbitControls } from "https://esm.sh/three@0.160.0/examples/jsm/controls/OrbitControls.js";
const CONFIG=__CONFIG__;
const SCALE_DATA=__SCALES__;
const errorBox=document.getElementById('err');
function showError(e){errorBox.style.display='block';errorBox.textContent='3D RENDER ERROR: '+(e?.message||String(e));console.error(e)}
window.addEventListener('error',e=>showError(e.error||e.message));
window.addEventListener('unhandledrejection',e=>showError(e.reason));
try{
const canvas=document.getElementById('view');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio||1,1.7));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;
const scene=new THREE.Scene();scene.fog=new THREE.FogExp2(0x100f09,.012);
const camera=new THREE.PerspectiveCamera(37,1,.1,220);camera.position.set(12.5,8.2,15.5);
const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.dampingFactor=.055;controls.minDistance=7;controls.maxDistance=45;controls.target.set(0,2.55,.15);controls.maxPolarAngle=Math.PI*.49;
scene.add(new THREE.HemisphereLight(0xffe8b0,0x241a08,1.55));
const key=new THREE.DirectionalLight(0xffe5a0,3.5);key.position.set(-9,15,10);key.castShadow=true;key.shadow.mapSize.set(2048,2048);key.shadow.camera.left=-18;key.shadow.camera.right=18;key.shadow.camera.top=18;key.shadow.camera.bottom=-18;scene.add(key);
const rim=new THREE.DirectionalLight(0xffb52e,2.7);rim.position.set(9,9,-12);scene.add(rim);
const fill=new THREE.PointLight(0xffd66c,32,28,2);fill.position.set(0,5,8);scene.add(fill);
const gold=new THREE.MeshStandardMaterial({color:0xd5a92e,roughness:.78,metalness:.28});
const goldLight=new THREE.MeshStandardMaterial({color:0xf0c64b,roughness:.67,metalness:.32});
const goldDark=new THREE.MeshStandardMaterial({color:0x8e6419,roughness:.86,metalness:.2});
const membraneMat=new THREE.MeshStandardMaterial({color:0xb78320,roughness:.88,metalness:.16,side:THREE.DoubleSide});
const hornMat=new THREE.MeshStandardMaterial({color:0x4d3a19,roughness:.72,metalness:.1});
const eyeMat=new THREE.MeshStandardMaterial({color:0xff3b08,emissive:0xff2400,emissiveIntensity:2.2,roughness:.2});
const mouthMat=new THREE.MeshStandardMaterial({color:0x24130b,roughness:.92});
const clawMat=new THREE.MeshStandardMaterial({color:0x382b19,roughness:.52,metalness:.18});
const root=new THREE.Group();root.name='KING_GHIDORAH_ROOT';scene.add(root);
const wingRig=[];
function mesh(geo,mat,parent,pos,rot){const m=new THREE.Mesh(geo,mat);m.position.set(pos.x,pos.y,pos.z);if(rot)m.rotation.set(rot.x||0,rot.y||0,rot.z||0);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function ball(parent,pos,scale,mat,rot){const m=mesh(new THREE.SphereGeometry(1,24,18),mat,parent,pos,rot);m.scale.set(scale.x,scale.y,scale.z);return m;}
function bone(parent,a,b,r1,r2,mat,radial=12){const A=new THREE.Vector3(a.x,a.y,a.z),B=new THREE.Vector3(b.x,b.y,b.z),d=new THREE.Vector3().subVectors(B,A),len=d.length();const m=mesh(new THREE.CylinderGeometry(r2,r1,len,radial,1),mat,parent,{x:(a.x+b.x)/2,y:(a.y+b.y)/2,z:(a.z+b.z)/2});m.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.normalize());return m;}
function curvedSpine(parent,points,radius,mat){for(let i=0;i<points.length-1;i++){const t=i/(points.length-1);bone(parent,points[i],points[i+1],radius*(1-t*.42),radius*(1-(i+1)/(points.length-1)*.42),mat,12);}}
function createBody(){
 const body=new THREE.Group();body.name='CENTRAL_GOLDEN_BODY';root.add(body);
 ball(body,{x:0,y:1.95,z:-.05},{x:.91,y:.68,z:1.7},gold);
 ball(body,{x:0,y:2.23,z:-.78},{x:.82,y:.58,z:.88},goldLight);
 ball(body,{x:0,y:1.54,z:.35},{x:.68,y:.28,z:1.18},goldDark);
 // Shoulder and hip muscle groups remain integrated with the torso.
 for(const s of [-1,1]){ball(body,{x:s*.58,y:1.92,z:-.82},{x:.42,y:.53,z:.66},gold);ball(body,{x:s*.5,y:1.78,z:1.0},{x:.38,y:.42,z:.58},goldLight);}
 // Dorsal ridges only: deliberately no circular or ring-shaped back pieces.
 for(let i=0;i<23;i++){const t=i/22,z=1.05-t*3.0,y=2.53+Math.sin(t*Math.PI)*.08,h=.19+Math.sin(t*Math.PI)*.2;bone(body,{x:0,y,z},{x:0,y:y+h,z:z-.12},.105,.004,hornMat,8);}
 return body;
}
function createHead(parent,side){
 const head=new THREE.Group();head.name=['LEFT_HEAD','CENTRAL_HEAD','RIGHT_HEAD'][side+1];
 const x=side*1.27;head.position.set(x,4.48,3.26);parent.add(head);
 // Long, narrow skull, tapered snout, lower jaw and brow.
 ball(head,{x:0,y:0,z:0},{x:.34,y:.31,z:.48},goldLight);
 ball(head,{x:0,y:-.105,z:.53},{x:.225,y:.17,z:.72},gold);
 ball(head,{x:0,y:-.205,z:1.02},{x:.175,y:.095,z:.34},goldDark);
 ball(head,{x:0,y:-.30,z:.86},{x:.16,y:.045,z:.42},mouthMat);
 for(const s of [-1,1]){
  ball(head,{x:s*.29,y:.105,z:.18},{x:.082,y:.075,z:.115},eyeMat);
  ball(head,{x:s*.18,y:.20,z:-.12},{x:.19,y:.09,z:.25},gold);
  bone(head,{x:s*.17,y:.23,z:-.10},{x:s*.39,y:.70,z:-.48},.13,.006,hornMat,10);
  bone(head,{x:s*.13,y:-.03,z:.82},{x:s*.13,y:-.12,z:1.27},.035,.004,hornMat,8);
  // small cheek spurs
  bone(head,{x:s*.27,y:-.02,z:.05},{x:s*.48,y:-.16,z:.42},.075,.004,goldDark,8);
 }
 for(let i=0;i<5;i++){const z=-.28-i*.15;bone(head,{x:0,y:.27,z},{x:0,y:.43,z:z-.12},.07,.002,hornMat,7);}
 return head;
}
function createNeck(side){
 const neck=new THREE.Group();neck.name='NECK_'+(side+2);root.add(neck);
 const start={x:side*.38,y:2.34,z:1.05};const finish={x:side*1.27,y:4.48,z:3.26};
 const pts=[];const segments=24;
 for(let i=0;i<=segments;i++){const t=i/segments;pts.push({x:start.x+(finish.x-start.x)*t+Math.sin(t*Math.PI)*side*.13,y:start.y+(finish.y-start.y)*t+.10*Math.sin(t*Math.PI),z:start.z+(finish.z-start.z)*t});}
 for(let i=0;i<segments;i++){const t=i/segments;bone(neck,pts[i],pts[i+1],.34-.13*t,.34-.13*(i+1)/segments,gold,14);}
 for(let i=0;i<segments;i+=2){const p=pts[i];bone(neck,{x:p.x,y:p.y+.19,z:p.z},{x:p.x+side*.08,y:p.y+.34,z:p.z-.08},.085,.003,hornMat,7);}
 return neck;
}
function createLeg(side){
 const leg=new THREE.Group();leg.name=side<0?'LEFT_HIND_LEG':'RIGHT_HIND_LEG';root.add(leg);
 const hip={x:side*.62,y:1.63,z:-.72},knee={x:side*.78,y:.91,z:-.28},ankle={x:side*.72,y:.20,z:.08};
 ball(leg,hip,{x:.39,y:.48,z:.43},gold);bone(leg,hip,knee,.31,.21,gold,16);ball(leg,knee,{x:.23,y:.24,z:.24},goldLight);bone(leg,knee,ankle,.20,.13,gold,14);
 ball(leg,{x:side*.72,y:.13,z:.32},{x:.30,y:.14,z:.40},gold);
 for(let toe=-1;toe<=1;toe++){const a={x:side*.72+toe*.13,y:.12,z:.42},b={x:side*.72+toe*.17,y:.07,z:.73};bone(leg,a,b,.085,.04,gold,9);bone(leg,b,{x:b.x,y:.045,z:b.z+.16},.04,.002,clawMat,8);}
 return leg;
}
function createTail(side){
 const tail=new THREE.Group();tail.name=side<0?'LEFT_TAIL':'RIGHT_TAIL';root.add(tail);
 const pts=[];const seg=42;
 for(let i=0;i<=seg;i++){const t=i/seg;pts.push({x:side*(.43+.18*Math.sin(t*4.2)),y:1.43-.68*t+.12*Math.sin(t*5.4),z:-1.42-5.05*t});}
 for(let i=0;i<seg;i++){const t=i/seg;bone(tail,pts[i],pts[i+1],.28*(1-t)+.025,.28*(1-(i+1)/seg)+.018,gold,10);}
 for(let i=4;i<seg-3;i+=3){const p=pts[i];const t=i/seg;bone(tail,{x:p.x,y:p.y+.12*(1-t),z:p.z},{x:p.x+side*.06,y:p.y+.27*(1-t),z:p.z-.10},.055,.002,hornMat,7);}
 ball(tail,pts[seg],{x:.085,y:.085,z:.22},goldDark);return tail;
}
function createWing(side){
 const wing=new THREE.Group();wing.name=side<0?'LEFT_COLOSSAL_BAT_WING':'RIGHT_COLOSSAL_BAT_WING';wing.position.set(side*.64,2.55,-.52);wing.scale.x=side*CONFIG.wingSize;root.add(wing);wingRig.push(wing);
 // The wing is a long, swept, finger-supported bat membrane, not a butterfly fan.
 const shape=new THREE.Shape();shape.moveTo(0,0);shape.quadraticCurveTo(.72,.62,1.35,1.12);shape.quadraticCurveTo(2.75,2.35,4.75,2.18);shape.quadraticCurveTo(6.0,2.0,7.05,1.18);shape.quadraticCurveTo(7.18,.75,6.95,.18);shape.quadraticCurveTo(6.55,-.34,6.15,-.54);shape.quadraticCurveTo(5.45,-.86,5.12,-1.20);shape.quadraticCurveTo(4.52,-.78,4.22,-1.43);shape.quadraticCurveTo(3.62,-.92,3.28,-1.66);shape.quadraticCurveTo(2.70,-1.05,2.34,-1.70);shape.quadraticCurveTo(1.75,-.90,1.38,-1.30);shape.quadraticCurveTo(.72,-.48,0,0);
 const geo=new THREE.ShapeGeometry(shape,18);const membrane=mesh(geo,membraneMat,wing,{x:0,y:0,z:0});membrane.material.side=THREE.DoubleSide;
 const s=side;const rootPt={x:0,y:0,z:.02},shoulder={x:s*1.35,y:1.12,z:0},elbow={x:s*3.55,y:2.13,z:-.10},wrist={x:s*5.25,y:1.72,z:-.20},tip={x:s*7.05,y:1.18,z:-.24};
 bone(wing,rootPt,shoulder,.29,.21,goldLight,14);bone(wing,shoulder,elbow,.22,.15,goldLight,12);bone(wing,elbow,wrist,.16,.10,goldLight,12);bone(wing,wrist,tip,.11,.025,goldLight,10);
 const fingerTips=[{x:s*6.92,y:.18,z:-.18},{x:s*5.12,y:-1.20,z:-.12},{x:s*3.28,y:-1.66,z:-.08},{x:s*1.38,y:-1.30,z:.02}];
 const fingerStarts=[wrist,elbow,elbow,shoulder];
 fingerTips.forEach((p,i)=>{bone(wing,fingerStarts[i],p,.095-i*.012,.012,goldLight,9);ball(wing,p,{x:.045,y:.045,z:.045},hornMat);});
 // Fine curved wing veins and membrane tension lines.
 for(let i=0;i<8;i++){const t=(i+1)/9;const start={x:s*(.55+t*1.05),y:.30+t*.68,z:.025};const end=fingerTips[Math.min(3,Math.floor(t*4))];const mid={x:(start.x+end.x)*.5,y:(start.y+end.y)*.5-.10,z:.04};const curve=new THREE.QuadraticBezierCurve3(new THREE.Vector3(start.x,start.y,start.z),new THREE.Vector3(mid.x,mid.y,mid.z),new THREE.Vector3(end.x,end.y,end.z));const line=mesh(new THREE.TubeGeometry(curve,16,.012,5,false),goldDark,wing,{x:0,y:0,z:0});line.castShadow=false;}
 return wing;
}
function createScales(){
 const geo=new THREE.IcosahedronGeometry(.045,0);const mat=new THREE.MeshStandardMaterial({color:0xe2b83e,roughness:.72,metalness:.24});
 const inst=new THREE.InstancedMesh(geo,mat,SCALE_DATA.length);inst.name='33000_UNIQUE_GOLDEN_SCALE_INSTANCES';inst.castShadow=true;inst.receiveShadow=true;
 const dummy=new THREE.Object3D();const color=new THREE.Color();
 for(let i=0;i<SCALE_DATA.length;i++){const [x,y,z,sx,sy,rot]=SCALE_DATA[i];dummy.position.set(x,y,z);dummy.rotation.set(.12*Math.sin(rot),rot,.08*Math.cos(rot));dummy.scale.set(sx/.045,sy/.045,1);dummy.updateMatrix();inst.setMatrixAt(i,dummy.matrix);const shade=.78+((i*37)%23)/100;color.setRGB(.70*shade,.48*shade,.12*shade);inst.setColorAt(i,color);}
 inst.instanceMatrix.needsUpdate=true;if(inst.instanceColor)inst.instanceColor.needsUpdate=true;root.add(inst);
}
function createGround(){const mat=new THREE.MeshStandardMaterial({color:0x17140c,roughness:.98,metalness:.02});const ground=mesh(new THREE.CircleGeometry(17,100),mat,scene,{x:0,y:-.06,z:0},{x:-Math.PI/2,y:0,z:0});ground.receiveShadow=true;}
function createAtmosphere(){const pts=[];for(let i=0;i<500;i++){const r=25+Math.random()*40,t=Math.random()*Math.PI*2,p=Math.random()*Math.PI;pts.push(r*Math.sin(p)*Math.cos(t),r*Math.cos(p)+9,r*Math.sin(p)*Math.sin(t));}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pts,3));scene.add(new THREE.Points(g,new THREE.PointsMaterial({color:0xe9c76b,size:.065,transparent:true,opacity:.52})));}
function assembleKingGhidorah(){createBody();for(const side of [-1,0,1]){createNeck(side);createHead(root,side);}createLeg(-1);createLeg(1);createTail(-1);createTail(1);createWing(-1);createWing(1);createScales();}
assembleKingGhidorah();createGround();createAtmosphere();
function resize(){const w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;renderer.setSize(w,h,false);camera.aspect=w/h;camera.fov=w<700?56:37;camera.updateProjectionMatrix();}
window.addEventListener('resize',resize);resize();
const clock=new THREE.Clock();function animate(){requestAnimationFrame(animate);const t=clock.getElapsedTime();root.position.y=Math.sin(t*.85)*.025;wingRig.forEach((w,i)=>{const dir=i===0?-1:1;w.rotation.z=dir*(.018+Math.sin(t*1.1+i*Math.PI)*.018);});controls.update();renderer.render(scene,camera);}animate();
}catch(e){showError(e);}
</script></body></html>"""
    return html.replace('__CONFIG__', settings).replace('__SCALES__', scales)


def main() -> None:
    apply_interface()
    st.markdown('<div class="gh-title">KING GHIDORAH</div><div class="gh-sub">THREE-HEADED GOLDEN TITAN · CINEMATIC 3D MODEL</div>', unsafe_allow_html=True)
    wing_size = st.slider('WING SIZE', min_value=0.65, max_value=1.45, value=DEFAULT_WING_SIZE, step=0.05)
    st.markdown('<div class="gh-frame">', unsafe_allow_html=True)
    components.html(build_scene_html(wing_size), height=765, scrolling=False)
    st.markdown('</div>', unsafe_allow_html=True)


if __name__ == '__main__':
    main()
